using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // ──────────────────────────────────────────────
    //  AddItem – happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInTotal()
    {
        // Arrange & Act
        _cart.AddItem("SKU-A", 2, 5.00m);

        // Assert
        Assert.AreEqual(10.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_TotalSumsAll()
    {
        // Arrange & Act
        _cart.AddItem("SKU-A", 1, 10.00m);
        _cart.AddItem("SKU-B", 3, 5.00m);

        // Assert – 10 + 15 = 25
        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_QuantityIsAccumulated()
    {
        // Arrange & Act
        _cart.AddItem("SKU-A", 2, 5.00m);
        _cart.AddItem("SKU-A", 3, 5.00m);

        // Assert – (2+3) × 5 = 25
        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSkuDifferentPrice_UsesLatestPrice()
    {
        // Arrange & Act
        _cart.AddItem("SKU-A", 2, 5.00m);
        _cart.AddItem("SKU-A", 1, 8.00m);

        // Assert – (2+1) × 8 = 24  (latest price wins)
        Assert.AreEqual(24.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_ZeroPrice_IsAllowed()
    {
        // Arrange & Act
        _cart.AddItem("FREEBIE", 1, 0.00m);

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    //  AddItem – validation / error cases
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void AddItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.AddItem(sku!, 1, 1.00m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU-A", quantity, 1.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU-A", 1, -1.00m));
    }

    // ──────────────────────────────────────────────
    //  RemoveItem – happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 10.00m);
        _cart.AddItem("SKU-B", 1, 20.00m);

        // Act
        _cart.RemoveItem("SKU-A");

        // Assert – only SKU-B remains
        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OnlyItem_CartBecomesEmpty()
    {
        // Arrange
        _cart.AddItem("SKU-A", 3, 7.00m);

        // Act
        _cart.RemoveItem("SKU-A");

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    //  RemoveItem – error cases
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_NonexistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsException<InvalidOperationException>(() => _cart.RemoveItem("GHOST"));
    }

    [TestMethod]
    public void RemoveItem_AlreadyRemovedSku_ThrowsInvalidOperationException()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 5.00m);
        _cart.RemoveItem("SKU-A");

        // Act & Assert
        Assert.ThrowsException<InvalidOperationException>(() => _cart.RemoveItem("SKU-A"));
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal – various states
    // ──────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    [DataRow(1, 9.99, 9.99, DisplayName = "Single unit")]
    [DataRow(5, 3.50, 17.50, DisplayName = "Multiple units")]
    [DataRow(100, 0.01, 1.00, DisplayName = "Many cheap items")]
    public void CalculateTotal_VariousQuantitiesAndPrices_ReturnsCorrectSum(
        int quantity, double price, double expectedTotal)
    {
        // Arrange
        _cart.AddItem("SKU-X", quantity, (decimal)price);

        // Assert
        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    //  ApplyCoupon – happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ApplyCoupon_Save10_ReducesTotalBy10Percent()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 100.00m);

        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Save20_ReducesTotalBy20Percent()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 50.00m);

        // Act
        _cart.ApplyCoupon("SAVE20");

        // Assert
        Assert.AreEqual(40.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CouponAppliedBeforeAddingItems_StillApplies()
    {
        // Arrange
        _cart.ApplyCoupon("SAVE10");

        // Act
        _cart.AddItem("SKU-A", 2, 50.00m);

        // Assert – 100 - 10% = 90
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_ReplacePreviousCoupon_OnlyLatestApplies()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");

        // Act – replace with SAVE20
        _cart.ApplyCoupon("SAVE20");

        // Assert – 20% off, not 10%
        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Save10_MultipleItemsDiscountedCorrectly()
    {
        // Arrange
        _cart.AddItem("SKU-A", 2, 30.00m); // 60
        _cart.AddItem("SKU-B", 1, 40.00m); // 40
        // subtotal = 100

        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert – 100 - 10% = 90
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    //  ApplyCoupon – error cases
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow("BADCODE", DisplayName = "Unknown code")]
    [DataRow("save10", DisplayName = "Wrong case")]
    [DataRow("", DisplayName = "Empty string")]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException(string code)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(code));
    }

    // ──────────────────────────────────────────────
    //  Integration-style: add, remove, coupon, total
    // ──────────────────────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddRemoveCouponTotal_ProducesCorrectResult()
    {
        // Arrange
        _cart.AddItem("WIDGET", 3, 10.00m);  // 30
        _cart.AddItem("GADGET", 2, 25.00m);  // 50
        _cart.RemoveItem("WIDGET");            // -30 → 50
        _cart.ApplyCoupon("SAVE20");           // 50 × 0.80 = 40

        // Assert
        Assert.AreEqual(40.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void FullWorkflow_AddSameSkuTwiceThenRemove_CartIsEmpty()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 5.00m);
        _cart.AddItem("SKU-A", 2, 5.00m);

        // Act
        _cart.RemoveItem("SKU-A");

        // Assert – removal removes the entire SKU, not just 1 unit
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }
}

